9	export default function LoginPage() {
10	  const router = useRouter();
11	  const [email, setEmail] = useState("");
12	  const [password, setPassword] = useState("");
13	  const [error, setError] = useState<string | null>(null);
14	  const [loading, setLoading] = useState(false);
15	
16	  async function handleSubmit(e: FormEvent) {
17	    e.preventDefault();
18	    setError(null);
19	    setLoading(true);
20	
21	    const supabase = createClient();
22	    const { error } = await supabase.auth.signInWithPassword({ email, password });
23	
24	    setLoading(false);
25	
26	    if (error) {
27	      setError(error.message);
28	      return;
29	    }
30	
31	    router.push("/dashboard");
32	    router.refresh();
33	  }
34	
35	  return (
36	    <AuthShell>
37	      <div className="mb-8 text-center">
38	        <div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-2xl bg-brand-600 shadow-lg shadow-brand-600/20">
39	          <span className="text-lg font-bold text-white">K</span>
40	        </div>
41	        <h1 className="text-xl font-bold text-zinc-900">Masuk ke KasirKu</h1>
42	        <p className="mt-1 text-sm text-zinc-500">
43	          Masuk dengan akun pemilik toko kamu
44	        </p>
45	      </div>
46	
47	      <form onSubmit={handleSubmit} className="space-y-4">
48	        <div>
49	          <label htmlFor="email" className="mb-1 block text-xs font-medium text-zinc-600">
50	            Email
51	          </label>
52	          <input
53	            id="email"
54	            type="email"
55	            autoComplete="email"
56	            required
57	            value={email}
58	            onChange={(e) => setEmail(e.target.value)}
59	            className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm transition-shadow focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
60	            placeholder="kamu@toko.com"
61	          />
62	        </div>
63	        <div>
64	          <div className="mb-1 flex items-center justify-between">
65	            <label htmlFor="password" className="block text-xs font-medium text-zinc-600">
66	              Password
67	            </label>
68	            <Link href="/forgot-password" className="text-xs font-medium text-brand-600 hover:underline">
69	              Lupa password?
70	            </Link>
71	          </div>
72	          <input
73	            id="password"
74	            type="password"
75	            autoComplete="current-password"
76	            required
77	            value={password}
78	            onChange={(e) => setPassword(e.target.value)}
79	            className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm transition-shadow focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
80	            placeholder="••••••••"
81	          />
82	        </div>
83	
84	        {error && (
85	          <p className="rounded-lg bg-red-50 px-3 py-2 text-xs text-red-600">{error}</p>
86	        )}
87	
88	        <button
89	          type="submit"
90	          disabled={loading}
91	          className="w-full rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white shadow-md shadow-brand-600/20 transition-all hover:bg-brand-700 hover:shadow-lg hover:shadow-brand-600/25 disabled:cursor-not-allowed disabled:opacity-60 disabled:shadow-none"
92	        >
93	          {loading ? "Memproses…" : "Masuk"}
94	        </button>
95	      </form>
96	
97	      <p className="mt-6 text-center text-sm text-zinc-500">
98	        Belum punya akun?{" "}
99	        <Link href="/signup" className="font-medium text-brand-600 hover:underline">
100	          Daftar
101	        </Link>
102	      </p>
103	    </AuthShell>
104	  );
105	}
