8	export default function ResetPasswordPage() {
9	  const router = useRouter();
10	  const [password, setPassword] = useState("");
11	  const [confirmPassword, setConfirmPassword] = useState("");
12	  const [error, setError] = useState<string | null>(null);
13	  const [loading, setLoading] = useState(false);
14	  const [done, setDone] = useState(false);
15	
16	  async function handleSubmit(e: FormEvent) {
17	    e.preventDefault();
18	    setError(null);
19	
20	    if (password !== confirmPassword) {
21	      setError("Password dan konfirmasi tidak sama.");
22	      return;
23	    }
24	    if (password.length < 6) {
25	      setError("Password minimal 6 karakter.");
26	      return;
27	    }
28	
29	    setLoading(true);
30	    const supabase = createClient();
31	    const { error } = await supabase.auth.updateUser({ password });
32	    setLoading(false);
33	
34	    if (error) {
35	      setError(error.message);
36	      return;
37	    }
38	
39	    setDone(true);
40	  }
41	
42	  if (done) {
43	    return (
44	      <AuthShell>
45	        <div className="text-center">
46	          <div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-2xl bg-brand-600 shadow-lg shadow-brand-600/20">
47	            <span className="text-lg font-bold text-white">K</span>
48	          </div>
49	          <h1 className="text-xl font-bold text-zinc-900">Password diperbarui</h1>
50	          <p className="mt-2 text-sm text-zinc-500">
51	            Password baru kamu sudah aktif.
52	          </p>
53	          <button
54	            onClick={() => {
55	              router.push("/dashboard");
56	              router.refresh();
57	            }}
58	            className="mt-6 w-full rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white shadow-md shadow-brand-600/20 transition-all hover:bg-brand-700 hover:shadow-lg hover:shadow-brand-600/25"
59	          >
60	            Ke Dashboard
61	          </button>
62	        </div>
63	      </AuthShell>
64	    );
65	  }
66	
67	  return (
68	    <AuthShell>
69	      <div className="mb-8 text-center">
70	        <div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-2xl bg-brand-600 shadow-lg shadow-brand-600/20">
71	          <span className="text-lg font-bold text-white">K</span>
72	        </div>
73	        <h1 className="text-xl font-bold text-zinc-900">Buat Password Baru</h1>
74	        <p className="mt-1 text-sm text-zinc-500">
75	          Masukkan password baru untuk akun kamu.
76	        </p>
77	      </div>
78	
79	      <form onSubmit={handleSubmit} className="space-y-4">
80	        <div>
81	          <label htmlFor="password" className="mb-1 block text-xs font-medium text-zinc-600">
82	            Password Baru
83	          </label>
84	          <input
85	            id="password"
86	            type="password"
87	            autoComplete="new-password"
88	            required
89	            value={password}
90	            onChange={(e) => setPassword(e.target.value)}
91	            className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm transition-shadow focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
92	            placeholder="Minimal 6 karakter"
93	          />
94	        </div>
95	        <div>
96	          <label
97	            htmlFor="confirmPassword"
98	            className="mb-1 block text-xs font-medium text-zinc-600"
99	          >
100	            Ulangi Password
101	          </label>
102	          <input
103	            id="confirmPassword"
104	            type="password"
105	            autoComplete="new-password"
106	            required
107	            value={confirmPassword}
108	            onChange={(e) => setConfirmPassword(e.target.value)}
109	            className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm transition-shadow focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
110	            placeholder="••••••••"
111	          />
112	        </div>
113	
114	        {error && (
115	          <p className="rounded-lg bg-red-50 px-3 py-2 text-xs text-red-600">{error}</p>
116	        )}
117	
118	        <button
119	          type="submit"
120	          disabled={loading}
121	          className="w-full rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white shadow-md shadow-brand-600/20 transition-all hover:bg-brand-700 hover:shadow-lg hover:shadow-brand-600/25 disabled:cursor-not-allowed disabled:opacity-60 disabled:shadow-none"
122	        >
123	          {loading ? "Menyimpan…" : "Simpan Password"}
124	        </button>
125	      </form>
126	    </AuthShell>
127	  );
128	}
