1	import { createServerClient } from "@supabase/ssr";
2	import { type NextRequest, NextResponse } from "next/server";
3	
4	export async function updateSession(request: NextRequest) {
5	  let supabaseResponse = NextResponse.next({ request });
6	
7	  const supabase = createServerClient(
8	    process.env.NEXT_PUBLIC_SUPABASE_URL!,
9	    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
10	    {
11	      cookies: {
12	        getAll() {
13	          return request.cookies.getAll();
14	        },
15	        setAll(cookiesToSet) {
16	          cookiesToSet.forEach(({ name, value }) =>
17	            request.cookies.set(name, value),
18	          );
19	          supabaseResponse = NextResponse.next({ request });
20	          cookiesToSet.forEach(({ name, value, options }) =>
21	            supabaseResponse.cookies.set(name, value, options),
22	          );
23	        },
24	      },
25	    },
26	  );
27	
28	  // Required: refreshes the auth token and keeps cookies in sync.
29	  // Do not add logic between createServerClient and this call.
30	  const {
31	    data: { user },
32	  } = await supabase.auth.getUser();
33	
34	  const authPages = ["/login", "/signup", "/forgot-password"];
35	  const isAuthPage = authPages.some((path) =>
36	    request.nextUrl.pathname.startsWith(path),
37	  );
38	  // /order/* adalah halaman self-order pelanggan (scan QR) — tanpa login.
39	  // /auth/callback menukar kode dari link email jadi sesi, sebelum user ada.
40	  // /reset-password sama kasusnya: link reset dari email membawa token di URL
41	  // fragment (#access_token=...), yang cuma bisa dibaca & diproses oleh
42	  // supabase-js di browser — belum ada sesi/cookie sama sekali saat request
43	  // pertama ini sampai ke middleware, jadi tidak boleh di-redirect ke /login
44	  // sebelum halamannya sempat jalan.
45	  // "/" adalah landing page publik untuk calon pengguna yang belum daftar.
46	  // /terms dan /privacy juga harus bisa dibaca tanpa login.
47	  // /rekomendasi-alat adalah halaman afiliasi publik — harus bisa diakses
48	  // pengunjung mana pun tanpa daftar/login dulu, itu tujuannya.
49	  // /blog adalah artikel SEO publik, sama alasannya.
50	  // /kalkulator-hpp adalah tool gratis publik (lead magnet) — harus bisa
51	  // dipakai siapa pun tanpa daftar/login dulu.
52	  // /sistem-akuntansi adalah halaman marketing publik untuk plan Finance
53	  // Only — sama seperti /kalkulator-hpp, harus bisa dibaca tanpa login.
54	  // /sitemap.xml dan /robots.txt dipanggil crawler mesin pencari tanpa sesi
55	  // browser sama sekali — harus tetap terbaca meski tidak ada user login.
56	  // /api/midtrans (webhook Midtrans) dan /api/cron (dipicu Vercel Cron) adalah
57	  // panggilan server-to-server tanpa sesi browser sama sekali — masing-masing
58	  // punya otentikasinya sendiri (verifikasi signature / CRON_SECRET), bukan
59	  // sesi login, jadi middleware tidak boleh me-redirect mereka ke /login.
60	  // /api/kalkulator-hpp-desktop/download dipanggil pembeli yang memang tidak
61	  // punya akun KasirKu sama sekali (guest checkout) — otentikasinya sendiri
62	  // lewat order_id+download_token di query string, bukan sesi login.
63	  const isPublicPath =
64	    isAuthPage ||
65	    request.nextUrl.pathname === "/" ||
66	    request.nextUrl.pathname.startsWith("/order") ||
67	    request.nextUrl.pathname.startsWith("/auth/callback") ||
68	    request.nextUrl.pathname.startsWith("/reset-password") ||
69	    request.nextUrl.pathname.startsWith("/terms") ||
70	    request.nextUrl.pathname.startsWith("/privacy") ||
71	    request.nextUrl.pathname.startsWith("/rekomendasi-alat") ||
72	    request.nextUrl.pathname.startsWith("/blog") ||
73	    request.nextUrl.pathname.startsWith("/kalkulator-hpp") ||
74	    request.nextUrl.pathname.startsWith("/sistem-akuntansi") ||
75	    request.nextUrl.pathname === "/sitemap.xml" ||
76	    request.nextUrl.pathname === "/robots.txt" ||
77	    request.nextUrl.pathname.startsWith("/api/midtrans") ||
78	    request.nextUrl.pathname.startsWith("/api/cron") ||
79	    request.nextUrl.pathname.startsWith("/api/kalkulator-hpp-desktop");
80	
81	  if (!user && !isPublicPath) {
82	    const url = request.nextUrl.clone();
83	    url.pathname = "/login";
84	    return NextResponse.redirect(url);
85	  }
86	
87	  if (user && isAuthPage) {
88	    const url = request.nextUrl.clone();
89	    url.pathname = "/dashboard";
90	    return NextResponse.redirect(url);
91	  }
92	
93	  return supabaseResponse;
94	}
